export function columnSqlType(kind: ColumnKind, dialect: "sqlite" | "postgres"): string {
  switch (kind) {
    case "integer": return dialect === "postgres" ? "BIGINT" : "INTEGER";
    case "boolean": return dialect === "postgres" ? "BOOLEAN" : "INTEGER";
    case "real": return dialect === "postgres" ? "DOUBLE PRECISION" : "REAL";
    case "blob": return dialect === "postgres" ? "BYTEA" : "BLOB";
    case "json": return dialect === "postgres" ? "JSONB" : "TEXT";
    case "timestamp":
    case "timestamp_nullable": return dialect === "postgres" ? "TIMESTAMPTZ" : "DATETIME";
    default: return "TEXT";
  }
}
